INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 2, 'theory', 'Quiz: trap-and-emulate, the x86 problem, and the workarounds');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 0, 'What happens in the trap-and-emulate scheme when the guest kernel executes a privileged instruction?', '["The instruction runs on the processor, and the monitor learns about it later from a log", "The processor raises a trap, the monitor imitates the action on the guest''s virtual state and returns control", "The guest crashes and restarts", "The monitor translates all of the guest''s code in advance"]', 1, 'The guest runs without privileges, so the processor itself stops the dangerous instruction. The monitor changes not the real registers but their virtual copies and hands control back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 1, 'Why does the POPF instruction get in the way of classic x86 virtualization?', '["It is too slow, and the monitor cannot keep up with handling it", "It is privileged, and it causes too many traps", "Outside ring zero it silently ignores a change to the interrupt flag and causes no trap, so the monitor never sees it", "It executes only inside the monitor"]', 2, 'POPF is sensitive but not privileged: Robin and Irvine found 17 such instructions. The guest is sure the flag is cleared, but in fact nothing happened, and there is no trap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 2, 'How does binary translation solve the problem of sensitive non-privileged instructions?', '["It scans the guest kernel code, replaces dangerous instructions with safe inserts or monitor calls, and caches the result", "It forbids the guest kernel from using flags", "It switches the guest entirely to emulation mode", "It replaces the guest''s kernel with the monitor''s kernel"]', 0, 'The guest stays unmodified, while the monitor pays with the time of the first pass and the complexity of the translator. Programs in ring 3 need no translation: there are no dangerous instructions there.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 3, 'What is a hypercall in paravirtualization?', '["An interrupt from a device", "A system call from a program into the guest kernel", "A trap that the processor raises on its own initiative", "An explicit call from the guest kernel to the hypervisor, like a system call but one level lower"]', 3, 'A paravirtualized kernel knows about the hypervisor and asks it to switch a page table or set a timer. This is fast and exact, but requires a modified OS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 4, 'Which quantity most strongly determines the speed of a software workaround or of paravirtualization?', '["The clock frequency of the host", "The size of the guest''s disk", "The number of protection rings", "The number of traps: each costs on the order of a thousand cycles or more"]', 3, 'An ordinary instruction costs a fraction of a cycle, while going into the monitor and back costs thousands. That is why translation, batched hypercalls, and virtual flags aim at reducing traps.');
